
'use client';

import { useRef, useEffect, useState, useCallback } from 'react';
import { useFirestore, useMemoFirebase, useCollection, errorEmitter, FirestorePermissionError } from '@/firebase';
import {
  collection,
  doc,
  setDoc,
  writeBatch,
  query,
  deleteDoc,
  getDocs,
  onSnapshot,
  updateDoc
} from 'firebase/firestore';
import type { Point, DrawingPath } from '@/types';
import { Button } from '../ui/button';
import { Eraser, Trash2 } from 'lucide-react';
import { useDebouncedCallback } from '@/hooks/use-debounce';

interface WhiteboardProps {
  roomId: string;
  canWrite: boolean;
}

const colors = [
  '#000000',
  '#EF4444',
  '#3B82F6',
  '#22C55E',
  '#F97316',
  '#8B5CF6',
];

export function Whiteboard({ roomId, canWrite }: WhiteboardProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [color, setColor] = useState('#000000');
  const currentPathRef = useRef<string | null>(null);
  const [localPaths, setLocalPaths] = useState<Record<string, DrawingPath>>({});

  const firestore = useFirestore();

  const pathsCollectionRef = useMemoFirebase(
    () => (firestore ? collection(firestore, `rooms/${roomId}/whiteboardData`) : null),
    [firestore, roomId]
  );
  
   useEffect(() => {
    if (!pathsCollectionRef) return;
    const q = query(pathsCollectionRef);
    const unsubscribe = onSnapshot(q, (snapshot) => {
        snapshot.docChanges().forEach((change) => {
            const pathData = change.doc.data() as DrawingPath;
            const pathId = change.doc.id;

            if (change.type === "added" || change.type === "modified") {
                if (pathId !== currentPathRef.current) {
                    setLocalPaths(prev => ({...prev, [pathId]: pathData}));
                }
            }
            if (change.type === "removed") {
                 setLocalPaths(prev => {
                    const newPaths = {...prev};
                    delete newPaths[pathId];
                    return newPaths;
                });
            }
        });
    }, (error) => {
        const contextualError = new FirestorePermissionError({
          operation: 'list',
          path: pathsCollectionRef.path,
        });
        errorEmitter.emit('permission-error', contextualError);
    });
    return () => unsubscribe();
   }, [pathsCollectionRef]);


  const getCanvasContext = useCallback(() => {
    const canvas = canvasRef.current;
    return canvas?.getContext('2d');
  }, []);

  const drawPath = useCallback(
    (ctx: CanvasRenderingContext2D, path: DrawingPath) => {
      if (!path || !path.points || path.points.length === 0) return;
      ctx.beginPath();
      ctx.strokeStyle = path.color;
      ctx.lineWidth = 5;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      ctx.moveTo(path.points[0].x, path.points[0].y);
      for (let i = 1; i < path.points.length; i++) {
        ctx.lineTo(path.points[i].x, path.points[i].y);
      }
      ctx.stroke();
    },
    []
  );

  const redrawCanvas = useCallback(() => {
    const canvas = canvasRef.current;
    const ctx = getCanvasContext();
    if (!canvas || !ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    Object.values(localPaths).forEach((path) => drawPath(ctx, path));
  }, [localPaths, getCanvasContext, drawPath]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const parent = canvas.parentElement;
    if (!parent) return;

    const resizeObserver = new ResizeObserver(() => {
      canvas.width = parent.offsetWidth;
      canvas.height = parent.offsetHeight;
      redrawCanvas();
    });
    resizeObserver.observe(parent);

    return () => resizeObserver.disconnect();
  }, [redrawCanvas]);

  useEffect(() => {
    redrawCanvas();
  }, [localPaths, redrawCanvas]);

  const getPointInCanvas = (e: MouseEvent | TouchEvent): Point | null => {
    const canvas = canvasRef.current;
    if (!canvas) return null;
    const rect = canvas.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    return { x: clientX - rect.left, y: clientY - rect.top };
  };

  const handleMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (!canWrite || !firestore || !pathsCollectionRef) return;
    const point = getPointInCanvas(e.nativeEvent);
    if (!point) return;

    setIsDrawing(true);

    const newPathDocRef = doc(pathsCollectionRef);
    currentPathRef.current = newPathDocRef.id;

    const newPath: DrawingPath = {
      id: newPathDocRef.id,
      color: color,
      points: [point],
    };
    
    setLocalPaths(prev => ({...prev, [newPath.id]: newPath}));
    setDoc(newPathDocRef, newPath).catch(error => {
      errorEmitter.emit('permission-error', new FirestorePermissionError({
          path: newPathDocRef.path,
          operation: 'create',
          requestResourceData: newPath,
      }));
    });
  };
  
  const handleMouseMove = useDebouncedCallback((point: Point | null) => {
    if (!isDrawing || !canWrite || !currentPathRef.current || !firestore || !point) return;

    const currentPath = localPaths[currentPathRef.current];
    if (currentPath) {
      const updatedPoints = [...currentPath.points, point];
      const updatedPath: DrawingPath = {
        ...currentPath,
        points: updatedPoints,
      };
      
      setLocalPaths(prev => ({...prev, [currentPathRef.current!]: updatedPath}));
      
      const pathDocRef = doc(firestore, `rooms/${roomId}/whiteboardData`, currentPathRef.current);
      updateDoc(pathDocRef, { points: updatedPoints }).catch(error => {
        errorEmitter.emit('permission-error', new FirestorePermissionError({
            path: pathDocRef.path,
            operation: 'update',
            requestResourceData: { points: updatedPoints },
        }));
      });
    }
  }, 10);
  
  const handleMouseUp = () => {
    setIsDrawing(false);
    currentPathRef.current = null;
  };

  const handleClear = async () => {
    if (!canWrite || !firestore || !pathsCollectionRef) return;
    
    const snapshot = await getDocs(pathsCollectionRef);
    if(snapshot.empty) return;

    setLocalPaths({});

    const batch = writeBatch(firestore);
    snapshot.docs.forEach((doc) => {
      batch.delete(doc.ref);
    });
    
    batch.commit().catch(error => {
        errorEmitter.emit('permission-error', new FirestorePermissionError({
            path: pathsCollectionRef.path,
            operation: 'delete',
        }));
    });
  };

  return (
    <div className="relative flex h-full w-full flex-col">
      <div className="flex items-center gap-2 border-b p-2">
        <div className="flex items-center gap-1 rounded-md border p-1">
          {colors.map((c) => (
            <button
              key={c}
              onClick={() => setColor(c)}
              className={`h-7 w-7 rounded-md transition-transform ${
                color === c ? 'scale-110 ring-2 ring-ring' : ''
              }`}
              style={{ backgroundColor: c }}
              disabled={!canWrite}
            />
          ))}
        </div>
        <Button
          variant={color === '#FFFFFF' ? 'secondary' : 'ghost'}
          size="icon"
          onClick={() => setColor('#FFFFFF')}
          disabled={!canWrite}
          title="Eraser"
        >
          <Eraser className="h-5 w-5" />
        </Button>
        <Button
          variant="ghost"
          size="icon"
          onClick={handleClear}
          disabled={!canWrite}
          title="Clear All"
        >
          <Trash2 className="h-5 w-5" />
        </Button>
        {!canWrite && (
          <span className="ml-auto text-sm text-muted-foreground">
            View only mode
          </span>
        )}
      </div>
      <div className="relative flex-1 bg-white">
        <canvas
          ref={canvasRef}
          onMouseDown={handleMouseDown}
          onMouseMove={isDrawing ? (e) => handleMouseMove(getPointInCanvas(e.nativeEvent)) : undefined}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
          className={`absolute inset-0 h-full w-full ${
            canWrite ? 'cursor-crosshair' : 'cursor-not-allowed'
          }`}
        />
      </div>
    </div>
  );
}
