
'use client';

import { useState, useEffect, useCallback } from 'react';
import { useFirestore, useMemoFirebase, useDoc, errorEmitter, FirestorePermissionError } from '@/firebase';
import { doc, updateDoc } from 'firebase/firestore';
import { useDebounce } from '@/hooks/use-debounce';
import { runCode } from '@/app/actions/code';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Loader2, Play, Terminal } from 'lucide-react';
import { ScrollArea } from '../ui/scroll-area';
import type { CodeEditorData } from '@/types';

interface CodeEditorProps {
  roomId: string;
  canWrite: boolean;
  initialCode: string;
  initialLanguage: string;
}

const languages = ['javascript', 'python', 'text'];

export function CodeEditor({
  roomId,
  canWrite,
  initialCode,
  initialLanguage,
}: CodeEditorProps) {
  const [code, setCode] = useState(initialCode);
  const [language, setLanguage] = useState(initialLanguage);
  const [input, setInput] = useState('');
  const [output, setOutput] = useState('');
  const [isRunning, setIsRunning] = useState(false);
  const debouncedCode = useDebounce(code, 500);

  const firestore = useFirestore();

  const codeEditorRef = useMemoFirebase(
    () =>
      firestore
        ? doc(firestore, `rooms/${roomId}/codeEditorData`, 'data')
        : null,
    [firestore, roomId]
  );

  const { data: remoteData } = useDoc<CodeEditorData>(codeEditorRef);

  useEffect(() => {
    if (remoteData) {
      if(remoteData.code !== debouncedCode) {
        setCode(remoteData.code);
      }
      setLanguage(remoteData.language);
      setInput(remoteData.input || '');
      setOutput(remoteData.output || '');
    }
  }, [remoteData]);

  useEffect(() => {
    if (canWrite && firestore && codeEditorRef && debouncedCode !== remoteData?.code) {
      updateDoc(codeEditorRef, { code: debouncedCode }).catch(error => {
         errorEmitter.emit('permission-error', new FirestorePermissionError({
            path: codeEditorRef.path,
            operation: 'update',
            requestResourceData: { code: debouncedCode },
        }));
      });
    }
  }, [debouncedCode, canWrite, firestore, codeEditorRef, remoteData?.code]);

  useEffect(() => {
    if (canWrite && firestore && codeEditorRef && language !== remoteData?.language) {
      updateDoc(codeEditorRef, { language: language }).catch(error => {
         errorEmitter.emit('permission-error', new FirestorePermissionError({
            path: codeEditorRef.path,
            operation: 'update',
            requestResourceData: { language: language },
        }));
      });
    }
  }, [language, canWrite, firestore, codeEditorRef, remoteData?.language]);


  const handleRunCode = async () => {
    setIsRunning(true);
    setOutput('');
    const result = await runCode(code, input);
    const newOutput = result.error ? `Error: ${result.error}` : result.output;
    setOutput(newOutput);
     if (firestore && codeEditorRef) {
      updateDoc(codeEditorRef, { output: newOutput, input: input }).catch(error => {
         errorEmitter.emit('permission-error', new FirestorePermissionError({
            path: codeEditorRef.path,
            operation: 'update',
            requestResourceData: { output: newOutput, input: input },
        }));
      });
    }
    setIsRunning(false);
  };

  return (
    <div className="flex h-full flex-col">
      <div className="flex items-center justify-between border-b p-2">
        <Select
          value={language}
          onValueChange={setLanguage}
          disabled={!canWrite}
        >
          <SelectTrigger className="w-[180px]">
            <SelectValue placeholder="Select language" />
          </SelectTrigger>
          <SelectContent>
            {languages.map((lang) => (
              <SelectItem key={lang} value={lang}>
                {lang.charAt(0).toUpperCase() + lang.slice(1)}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Button onClick={handleRunCode} disabled={isRunning}>
          {isRunning ? (
            <Loader2 className="mr-2 h-4 w-4 animate-spin" />
          ) : (
            <Play className="mr-2 h-4 w-4" />
          )}
          Run
        </Button>
      </div>
      <div className="grid flex-1 flex-col overflow-hidden p-2 md:grid-cols-2 md:gap-4">
        <div className="flex h-full flex-col">
          <label htmlFor="code-editor" className="mb-2 text-sm font-medium">
            Code
          </label>
          <Textarea
            id="code-editor"
            value={code}
            onChange={(e) => setCode(e.target.value)}
            readOnly={!canWrite}
            placeholder="Write your code here..."
            className="font-code h-full flex-1 resize-none bg-muted/30"
          />
        </div>
        <div className="mt-4 flex flex-col space-y-4 overflow-auto md:mt-0">
          <div className="flex h-1/2 flex-col">
            <label htmlFor="input" className="mb-2 text-sm font-medium">
              Input
            </label>
            <Textarea
              id="input"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Provide input for your code..."
              className="font-code flex-1 resize-none"
            />
          </div>
          <div className="flex h-1/2 flex-col">
            <label
              htmlFor="output"
              className="mb-2 flex items-center gap-2 text-sm font-medium"
            >
              <Terminal className="h-4 w-4" /> Output
            </label>
            <ScrollArea className="h-full rounded-md border bg-muted/30 p-4">
              <pre className="font-code whitespace-pre-wrap text-sm">
                {output || 'Code output will appear here.'}
              </pre>
            </ScrollArea>
          </div>
        </div>
      </div>
      {!canWrite && (
        <div className="border-t p-2 text-center text-sm text-muted-foreground">
          View only mode
        </div>
      )}
    </div>
  );
}

