
'use client';

import { useEffect, useState, useMemo } from 'react';
import {
  useUser,
  useFirebaseApp,
  useFirestore,
  useDoc,
  useMemoFirebase,
} from '@/firebase';
import {
  doc,
  setDoc,
  updateDoc,
  onSnapshot,
  serverTimestamp,
} from 'firebase/firestore';
import type { Room, Participant, CodeEditorData } from '@/types';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Whiteboard } from './whiteboard';
import { CodeEditor } from './code-editor';
import { ParticipantsSidebar } from './participants-sidebar';
import { Palette, Code, Loader2 } from 'lucide-react';
import Link from 'next/link';
import { Skeleton } from '../ui/skeleton';
import { getAuth } from 'firebase/auth';
import {
  initiateEmailSignUp,
  initiateEmailSignIn,
} from '@/firebase/non-blocking-login';
import { Input } from '../ui/input';
import { Label } from '../ui/label';

export default function RoomClient({ roomId }: { roomId: string }) {
  const { user, isUserLoading } = useUser();
  const firestore = useFirestore();
  const [error, setError] = useState<string | null>(null);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [authError, setAuthError] = useState<string | null>(null);

  const app = useFirebaseApp();
  const auth = getAuth(app);

  const roomRef = useMemoFirebase(
    () => (firestore ? doc(firestore, 'rooms', roomId) : null),
    [firestore, roomId]
  );
  const { data: room, isLoading: isRoomLoading } = useDoc<Room>(roomRef);

  const codeEditorRef = useMemoFirebase(
    () =>
      firestore ? doc(firestore, `rooms/${roomId}/codeEditorData`, 'data') : null,
    [firestore, roomId]
  );
  const { data: codeEditorData, isLoading: isCodeEditorLoading } =
    useDoc<CodeEditorData>(codeEditorRef);

  const loading = isUserLoading || isRoomLoading || isCodeEditorLoading;

  const handleSignUp = async () => {
    if (!email || !password) {
      setAuthError('Please enter email and password.');
      return;
    }
    setAuthError(null);
    initiateEmailSignUp(auth, email, password);
  };

  const handleSignIn = async () => {
    if (!email || !password) {
      setAuthError('Please enter email and password.');
      return;
    }
    setAuthError(null);
    initiateEmailSignIn(auth, email, password);
  };

  useEffect(() => {
    if (!firestore || !user || !roomId) return;

    const participantRef = doc(firestore, `rooms/${roomId}`);

    const unsubscribe = onSnapshot(participantRef, async (docSnap) => {
      if (docSnap.exists()) {
        const currentMembers = docSnap.data().members || {};
        if (!currentMembers[user.uid]) {
          await updateDoc(participantRef, {
            [`members.${user.uid}`]: {
              uid: user.uid,
              name: user.displayName || user.email || 'Anonymous',
              avatar: user.photoURL || '',
            },
          });
        }
      } else {
        setError(
          'Room not found. It may have been deleted or the ID is incorrect.'
        );
      }
    });

    return () => {
      unsubscribe();
      // Note: onDisconnect logic for removing user is more complex with Firestore
      // and often handled with a Cloud Function listening to Realtime Database's presence system.
      // For simplicity in a client-only app, we might leave stale users.
    };
  }, [firestore, user, roomId]);

  if (loading) {
    return (
      <div className="flex h-screen w-full flex-col">
        <header className="flex h-16 shrink-0 items-center justify-between border-b px-4 md:px-6">
          <Skeleton className="h-8 w-32" />
          <Skeleton className="h-8 w-24" />
        </header>
        <div className="flex flex-1 overflow-hidden">
          <div className="flex-1 overflow-auto space-y-4 p-4 md:p-6">
            <Skeleton className="h-10 w-64" />
            <Skeleton className="aspect-video w-full" />
          </div>
          <aside className="hidden w-72 flex-col space-y-4 border-l bg-muted/40 p-4 md:flex">
            <Skeleton className="h-8 w-full" />
            <Skeleton className="h-10 w-full" />
            <Skeleton className="h-10 w-full" />
            <Skeleton className="h-10 w-full" />
          </aside>
        </div>
      </div>
    );
  }

  if (!user) {
    return (
      <div className="flex h-screen flex-col items-center justify-center gap-4 p-4 text-center">
        <div className="w-full max-w-sm space-y-4">
          <div className="space-y-2">
            <h2 className="text-2xl font-bold">
              Please sign in to join the room.
            </h2>
            <p className="text-muted-foreground">
              Collaboration requires you to be logged in.
            </p>
          </div>
          <div className="space-y-2">
            <Label htmlFor="email">Email</Label>
            <Input
              id="email"
              type="email"
              placeholder="m@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="password">Password</Label>
            <Input
              id="password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
          </div>
          {authError && (
            <p className="text-sm text-destructive">{authError}</p>
          )}
          <div className="flex gap-2">
            <Button className="w-full" onClick={handleSignIn}>
              Sign In
            </Button>
            <Button
              variant="secondary"
              className="w-full"
              onClick={handleSignUp}
            >
              Sign Up
            </Button>
          </div>
          <Button variant="link" asChild>
            <Link href="/">Back to Home</Link>
          </Button>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex h-screen flex-col items-center justify-center gap-4 text-center">
        <h2 className="text-2xl font-bold text-destructive">{error}</h2>
        <Button variant="link" asChild>
          <Link href="/">Go to Homepage</Link>
        </Button>
      </div>
    );
  }

  if (!room) {
    return (
      <div className="flex h-screen items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  const canWriteWhiteboard = room.writingPowerId === user.uid;
  const canWriteCode = codeEditorData?.writingPowerId === user.uid;
  const isHost = room.hostId === user.uid;

  return (
    <div className="flex h-screen w-full flex-col">
      <header className="flex h-16 shrink-0 items-center justify-between border-b bg-background px-4 md:px-6">
        <div className="flex items-center gap-2">
          <Link href="/" className="flex items-center gap-2 font-semibold">
            <svg
              width="24"
              height="24"
              viewBox="0 0 32 32"
              fill="none"
              xmlns="http://www.w3.org/2000/svg"
            >
              <rect
                width="32"
                height="32"
                rx="8"
                fill="hsl(var(--primary))"
              />
              <path
                d="M10 10H22V22H10V10Z"
                stroke="hsl(var(--primary-foreground))"
                strokeWidth="2"
              />
              <path
                d="M14 14H18"
                stroke="hsl(var(--primary-foreground))"
                strokeWidth="2"
                strokeLinecap="round"
              />
              <path
                d="M16 14V18"
                stroke="hsl(var(--primary-foreground))"
                strokeWidth="2"
                strokeLinecap="round"
              />
            </svg>
            <span>CollabCanvas</span>
          </Link>
        </div>
      </header>
      <div className="flex flex-1 overflow-hidden">
        <main className="flex-1 overflow-auto">
          <Tabs defaultValue="whiteboard" className="flex h-full flex-col">
            <div className="flex items-center border-b p-4">
              <TabsList>
                <TabsTrigger value="whiteboard">
                  <Palette className="mr-2 h-4 w-4" />
                  Whiteboard
                </TabsTrigger>
                <TabsTrigger value="code">
                  <Code className="mr-2 h-4 w-4" />
                  Code Editor
                </TabsTrigger>
              </TabsList>
            </div>
            <TabsContent
              value="whiteboard"
              className="m-0 flex-1 overflow-auto"
            >
              <Whiteboard
                roomId={roomId}
                canWrite={canWriteWhiteboard}
              />
            </TabsContent>
            <TabsContent value="code" className="m-0 flex-1 overflow-auto">
              <CodeEditor
                roomId={roomId}
                canWrite={canWriteCode}
                initialCode={codeEditorData?.code || ''}
                initialLanguage={codeEditorData?.language || 'javascript'}
              />
            </TabsContent>
          </Tabs>
        </main>
        <ParticipantsSidebar
          roomId={roomId}
          participants={Object.values(room.members || {})}
          hostId={room.hostId}
          writingPowerId={room.writingPowerId}
          codeWritingPowerId={codeEditorData?.writingPowerId}
          currentUserId={user.uid}
          isHost={isHost}
        />
      </div>
    </div>
  );
}

    